const STORE = {
  a: 'alpha',
  b: 'bravo',
  c: 'charlie',
};

export async function listTools() {
  return [{
    name: 'batch_lookup',
    description: 'Look up multiple ids in one call. Returns one result per id in input order; unknown ids are reported individually without aborting the batch.',
    inputSchema: {
      type: 'object',
      properties: {
        ids: {
          type: 'array',
          items: { type: 'string' },
          minItems: 1,
          description: 'Non-empty array of id strings to look up.',
        },
      },
      required: ['ids'],
      additionalProperties: false,
    },
  }];
}

function fail(message, code = -32602) {
  const err = new Error(message);
  err.code = code;
  throw err;
}

function validateArgs(args, schema) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    fail('arguments must be an object');
  }
  // check additional properties
  const allowed = Object.keys(schema.properties);
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      fail(`unexpected argument: ${key}`);
    }
  }
  // check required
  for (const req of schema.required) {
    if (!(req in args)) {
      fail(`missing required argument: ${req}`);
    }
  }
  // validate ids
  const ids = args.ids;
  if (!Array.isArray(ids)) {
    fail('ids must be an array');
  }
  if (ids.length === 0) {
    fail('ids must be a non-empty array');
  }
  for (const id of ids) {
    if (typeof id !== 'string') {
      fail('ids must be an array of strings');
    }
  }
}

export async function callTool(name, args = {}) {
  const tools = await listTools();
  const tool = tools.find(t => t.name === name);
  if (!tool) {
    fail(`unknown tool: ${name}`, -32601);
  }
  validateArgs(args || {}, tool.inputSchema);
  if (name === 'batch_lookup') {
    const results = args.ids.map(id => {
      if (Object.prototype.hasOwnProperty.call(STORE, id)) {
        return { id, ok: true, value: STORE[id] };
      }
      return { id, ok: false, error: `id not found: ${id}` };
    });
    return {
      content: [{ type: 'text', text: JSON.stringify({ results }) }],
    };
  }
  fail(`unknown tool: ${name}`, -32601);
}
